// Original starter curriculum written for Spanish-speaking Sauna Stilo users.
// This is an introductory practice bank, not a CEFR certificate or a complete language course.
import 'dart:convert';
class LanguagePair {
 final String spanish, foreign;
 const LanguagePair(this.spanish,this.foreign);
}
class StiloLesson {
 final String id,language,title,tip; final int order; final List<LanguagePair> pairs;
 const StiloLesson(this.id,this.language,this.title,this.tip,this.order,this.pairs);
 String get languageName=>language=='en'?'Inglés':'Francés';
 String get locale=>language=='en'?'en-US':'fr-FR';
}
final stiloLessons = (jsonDecode(_catalog) as List).map((raw) {
 final d=Map<String,dynamic>.from(raw as Map);
 return StiloLesson(d['id'],d['language'],d['title'],d['tip'],d['order'],
  List<LanguagePair>.unmodifiable((d['pairs'] as List).map((p)=>LanguagePair(p['es'],p['foreign']))));
}).toList(growable:false);
StiloLesson stiloLesson(String id)=>stiloLessons.firstWhere((l)=>l.id==id);
